using System; using WanderlightOnline; class Program { static void Main() { var inventory = new Inventory(); Console.WriteLine("=== Debug Inventory Capacity Test ==="); bool result1 = inventory.TryAdd("Potion", ItemCategory.Consumable, 21); Console.WriteLine($"Add 21 Potions: {result1}"); bool result2 = inventory.TryAdd("Sword", ItemCategory.Equipment, 1); bool result3 = inventory.TryAdd("Sword", ItemCategory.Equipment, 1); Console.WriteLine($"Add Sword 1: {result2}"); Console.WriteLine($"Add Sword 2: {result3}"); int usedSlots = 0; for (int i = 0; i < inventory.Slots.Length; i++) { if (inventory.Slots[i] != null) { usedSlots++; Console.WriteLine($"Slot {i}: {inventory.Slots[i].ItemType} x{inventory.Slots[i].Quantity} ({inventory.Slots[i].Category})"); } } Console.WriteLine($"Used slots so far: {usedSlots}"); Console.WriteLine($"Available slots: {12 - usedSlots}"); for (int i = 4; i <= 12; i++) { bool canAdd = inventory.TryAdd($"Item{i}", ItemCategory.Equipment, 1); Console.WriteLine($"Add Item{i}: {canAdd}"); if (!canAdd) break; } usedSlots = 0; for (int i = 0; i < inventory.Slots.Length; i++) { if (inventory.Slots[i] != null) { usedSlots++; } } Console.WriteLine($"Final used slots: {usedSlots}"); bool finalAdd = inventory.TryAdd("NewItem", ItemCategory.Equipment, 1); Console.WriteLine($"Add NewItem (should fail): {finalAdd}"); } }
